#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int N, K, U;
    if (scanf("%d %d %d", &N, &K, &U) != 3) return 0;

    int M = N * K;

    int *head = (int *)malloc((U + 1) * sizeof(int));
    int *to = (int *)malloc(M * sizeof(int));
    int *next = (int *)malloc(M * sizeof(int));

    for (int i = 1; i <= U; i++) {
        head[i] = -1;
    }

    int edge = 0;

    for (int card = 1; card <= N; card++) {
        for (int j = 0; j < K; j++) {
            int x;
            scanf("%d", &x);

            to[edge] = card;
            next[edge] = head[x];
            head[x] = edge++;
        }
    }

    int *cnt = (int *)calloc(N + 1, sizeof(int));
    int *finish = (int *)calloc(N + 1, sizeof(int));

    for (int pos = 1; pos <= U; pos++) {
        int x;
        scanf("%d", &x);

        for (int e = head[x]; e != -1; e = next[e]) {
            int card = to[e];

            if (finish[card]) continue;

            cnt[card]++;
            if (cnt[card] == K) {
                finish[card] = pos;
            }
        }
    }

    int best = U + 1;

    for (int card = 1; card <= N; card++) {
        if (finish[card] < best) {
            best = finish[card];
        }
    }

    int first = 1;

    for (int card = 1; card <= N; card++) {
        if (finish[card] == best) {
            if (!first) printf(" ");
            printf("%d", card);
            first = 0;
        }
    }

    printf("\n");

    free(head);
    free(to);
    free(next);
    free(cnt);
    free(finish);

    return 0;
}
